/* ============================================================================
   STORAGE KEYS
   users_v1   — shared  — { [emailLower]: { name, email, password, position,
                            experience, role, createdAt } }
   session_v1 — personal — { email }  (keeps this browser/account signed in)
   content_v1 — shared  — { drills, focusPoints, offIceWorkouts, dailyAssignments }

   NOTE ON SECURITY: this is a UX prototype, not production auth. Passwords
   are stored in plain text in the artifact's shared `db` capability, which
   is readable by any signed-in member of the org this artifact is
   published under. Do not reuse a real password here. A production
   build should use a real auth provider (e.g. Supabase Auth) with hashed
   credentials and server-side session tokens.

   NOTE ON HOSTING: users_v1 and content_v1 are "shared" keys, which means
   they live in claude.use("db") — this artifact MUST be published with
   capabilities: { db: {}, assets: {} } or sign-up/sign-in and drill photo/
   video uploads will silently do nothing (every read/write/upload no-ops).
   Both capabilities are org-internal: they only work for viewers signed in
   to the same Claude org that published the artifact, so this cannot power
   public sign-ups or uploads from people outside that org. session_v1 and
   the daily progress keys are "personal" keys — those just use the
   browser's localStorage, so they never leave the viewer's device and
   don't need any capability. Drill photos/videos an admin uploads go
   through claude.use("assets") — the returned asset id is what's saved on
   the drill in `db` (imageAssetId/videoAssetId); the returned url is used
   directly as the <img>/<video> src.
   ============================================================================ */

const LOGO_SRC = "data:image/png;base64,";
// Original full-color (black + red) mark, used only on the white print sheet.
const LOGO_PRINT_SRC = "data:image/png;base64,";
const BADGE_LOGO_SRC = "data:image/png;base64,";
// Real training photography, supplied by the brand. Used as the drill,
// focus point, and off-ice visuals across cards and detail pages.
const DRILL_IMG = "data:image/jpeg;base64,";
const FOCUS_IMG = "data:image/jpeg;base64,";
const OFFICE_IMG = "data:image/jpeg;base64,";
const GAME_DAY_BANNER_SRC = "data:image/jpeg;base64,";


const USERS_KEY = "users_v1";
const SESSION_KEY = "session_v1";
const CONTENT_KEY = "content_v1";

// Coach/admin sign-up is invite-only: the public form only ever creates a
// "goalie" account. Sharing a link with #invite=<code> appended pre-fills
// this code and offers the coach role during sign-up. Change this to your
// own private value before sharing — since this is a client-side prototype
// with no server, anyone who reads the page source could find this string,
// so treat it as a shared secret between you and people you trust, not as
// real access control. A production build should check invites server-side.
const COACH_INVITE_CODE = "10DTENDY-COACH-2026";

const _now = new Date();
const TODAY_DATE = new Date(_now.getFullYear(), _now.getMonth(), _now.getDate());
const WEEKDAY_NAMES = ["Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"];
const MONTH_NAMES = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];
const EXPERIENCE_LEVELS = ["Youth", "Junior", "Pro"];

const DEFAULT_WELCOME = {
  title: "Welcome to 10DTendy",
  body: "Every day you'll get three things to work on: a Drill, a Practice Focus, and an Off-Ice session — all set by your coach for your level.\nOpen the Today tab each day to see what's assigned, work through it, and check things off as you complete them.\nGot a game or a scheduled rest day? Mark it on your Profile calendar and your Today page will automatically show the right content instead of a normal training day.\nTrack your save percentage, rest days and more over time on the Progress tab.\nLet's get to work.",
  videoUrl: "", videoAssetId: null,
};
const DEFAULT_ANNOUNCEMENT = { enabled: false, id: null, title: "", body: "", videoUrl: "", videoAssetId: null };

function dateKey(d) {
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
}
function addDays(d, n) {
  const next = new Date(d);
  next.setDate(next.getDate() + n);
  return next;
}
// Goalies can only look back this many days from TODAY_DATE — older content isn't reachable.
const MAX_DAYS_BACK = 2;

// Daily assignments used to be one flat {drillId,focusId,workoutId} per date, shared by
// every goalie. Now each date holds one of those per experience level. Old saves that still
// have the flat shape get the same assignment copied to all three levels, once, on load.
function migrateDailyAssignments(dailyAssignments) {
  const out = {};
  for (const [key, val] of Object.entries(dailyAssignments || {})) {
    const isOldShape = val && (val.drillId !== undefined || val.focusId !== undefined || val.workoutId !== undefined);
    out[key] = isOldShape
      ? { Youth: val, Junior: val, Pro: val }
      : val;
  }
  return out;
}
// Experience levels were originally named Beginner/Intermediate/Advanced. Remap any
// data still keyed or valued with the old names, once, on load.
const LEVEL_RENAME_MAP = { Beginner: "Youth", Intermediate: "Junior", Advanced: "Pro" };
function renameLevelKeys(dailyAssignments) {
  const out = {};
  for (const [key, day] of Object.entries(dailyAssignments || {})) {
    const next = {};
    for (const [lvl, val] of Object.entries(day || {})) {
      next[LEVEL_RENAME_MAP[lvl] || lvl] = val;
    }
    out[key] = next;
  }
  return out;
}
function uid(prefix) {
  return prefix + "_" + Date.now().toString(36) + Math.random().toString(36).slice(2, 6);
}

// A goalie's own calendar marking always wins; "none" is an explicit personal override
// (e.g. "I know the coach scheduled a rest day, but I'm playing") that beats the coach's
// team-wide schedule for that date + experience level. Absent personal marking falls back
// to whatever the coach scheduled for that level in the Daily Training planner.
function resolveDayType(u, content, dateKeyStr, level) {
  const personal = (u.dayTypes || {})[dateKeyStr];
  if (personal === "none") return null;
  if (personal) return personal;
  const scheduled = content.dailyAssignments[dateKeyStr]?.[level];
  return scheduled && scheduled.isRestDay ? "rest" : null;
}

// The notification bell's content — always computed fresh from today's date and the
// goalie's own calendar marking, never stored, so it can't go stale or need a "seen"
// flag: a game-day reminder for today, and a "get back to training" nudge the day
// after a marked rest day. Coaches don't have a personal schedule, so they get none.
function getReminders(user, content, level) {
  if (!user || user.role === "coach" || !content) return [];
  const reminders = [];
  if (resolveDayType(user, content, dateKey(TODAY_DATE), level) === "game") {
    reminders.push({ id: "game", text: "Game day today — good luck out there." });
  }
  if (resolveDayType(user, content, dateKey(addDays(TODAY_DATE, -1)), level) === "rest") {
    reminders.push({ id: "rest", text: "You rested yesterday — time to get back to training today." });
  }
  return reminders;
}

// The 3 site-wide default images (drill/focus/office fallbacks) can be replaced and
// re-cropped by the coach from the admin "Front Page" section. Focal points are stored
// as a CSS object-position value — "x% y%" from the pixel-precise picker, or (from
// before that picker existed) a keyword pair like "left top" — both are valid CSS.
const FOCAL_KEYWORD_PCT = { left: 0, center: 50, right: 100, top: 0, bottom: 100 };
function parseFocalPoint(value) {
  const [xRaw, yRaw] = (value || "center center").trim().split(/\s+/);
  const pct = (raw) => (raw?.endsWith("%") ? parseFloat(raw) : FOCAL_KEYWORD_PCT[raw] ?? 50);
  return { x: Math.max(0, Math.min(100, pct(xRaw) || 0)), y: Math.max(0, Math.min(100, pct(yRaw) || 0)) };
}

// itemUrl (a per-item photo) always wins and is never re-cropped by branding settings.
function brandImage(itemUrl, entry, fallback) {
  if (itemUrl) return { src: itemUrl, style: undefined };
  return { src: entry?.url || fallback, style: { objectPosition: entry?.focalPoint || "center center" } };
}

