/* ============================================================================
   STORAGE HELPERS
   ============================================================================ */

// Guards against a storage call that never resolves (seen in some preview
// contexts) — without this, a hung call left the UI stuck on "Please wait…"
// forever with no visible error, which is exactly what looked like "nothing
// happened" when clicking Create account.
function withTimeout(promise, ms = 1800) {
  return Promise.race([
    promise,
    new Promise((resolve) => setTimeout(() => resolve(undefined), ms)),
  ]);
}

// Shared data (accounts, content) lives in the artifact's `db` capability —
// this artifact must be published with capabilities: { db: {} }, or every
// db.use() call below resolves null and shared reads/writes are silently
// no-ops. `db` is org-internal: only signed-in members of the publishing
// org can read/write it, so an account created by one signed-in viewer is
// visible to any other signed-in org member who opens this artifact.
// Personal, browser-local data (the login session, today's checkbox
// progress) doesn't need `db` at all — it's just localStorage.
let dbPromise = null;
function getDb() {
  if (!dbPromise) {
    dbPromise = (typeof window !== "undefined" && window.claude?.use)
      ? window.claude.use("db")
      : Promise.resolve(null);
  }
  return dbPromise;
}

// Drill photos/videos an admin uploads live in the `assets` capability —
// this artifact must also be published with capabilities: { assets: {} }.
// upload() resolves a durable {id, url}; the id is what gets saved on the
// drill (in `db`), and `url` is used directly as the <img>/<video> src.
let assetsPromise = null;
function getAssets() {
  if (!assetsPromise) {
    assetsPromise = (typeof window !== "undefined" && window.claude?.use)
      ? window.claude.use("assets")
      : Promise.resolve(null);
  }
  return assetsPromise;
}

async function getJSON(key, shared) {
  if (!shared) {
    try {
      const raw = localStorage.getItem(key);
      return raw ? JSON.parse(raw) : null;
    } catch {
      return null;
    }
  }
  try {
    const db = await withTimeout(getDb());
    if (!db) return null;
    const snap = await withTimeout(db.doc("app/" + key).get());
    return snap?.exists ? (snap.data().value ?? null) : null;
  } catch {
    return null;
  }
}
async function setJSON(key, value, shared) {
  if (!shared) {
    try {
      localStorage.setItem(key, JSON.stringify(value));
      return true;
    } catch {
      return false;
    }
  }
  try {
    const db = await withTimeout(getDb());
    if (!db) return false;
    await withTimeout(db.doc("app/" + key).set({ value }));
    return true;
  } catch {
    return false;
  }
}

// A per-user field write (a day marked, a game logged, a password changed, the
// online heartbeat) used to read the whole users_v1 blob, patch one user, and
// write the whole blob back — last-writer-wins, so two of these racing (most
// commonly the 60s heartbeat landing mid-edit) could silently drop whichever
// wrote first. `update()` merges nested objects server-side instead, so this
// only ever touches the one user's named fields, never the rest of the doc.
async function updateUserFields(email, patch) {
  // A merge write auto-creates whatever nested path it's given — so a falsy email
  // (a stale caller firing after logout, a not-yet-loaded account) would silently
  // write a corrupt "undefined" ghost user instead of failing loudly. Refuse it.
  if (!email) return false;
  try {
    const db = await withTimeout(getDb());
    if (!db) return false;
    await withTimeout(db.doc("app/" + USERS_KEY).update({ value: { [email]: patch } }));
    return true;
  } catch {
    return false;
  }
}

// Same idea as updateUserFields, but for the shared content doc (drills, focus
// points, off-ice workouts, the daily planner, branding, welcome/announcement, media).
// Every admin save used to read the whole content_v1 blob, compute a full replacement,
// and .set() it back — so a coach editing a drill while another coach (or this same
// coach in a second tab) saved a focus point at the same moment would silently lose
// whichever save landed first, since .set() replaces the ENTIRE document. Only the
// top-level fields actually being written are patched here, via a merge write, so an
// edit to `drills` never touches `focusPoints`/`branding`/etc. even if the caller's
// own in-memory `content` is stale on every other field. This does NOT protect two
// concurrent edits to the SAME field (e.g. two coaches both editing `drills` at once)
// — that would need per-item documents instead of one array field, a bigger change.
async function updateContentFields(patch) {
  if (!patch || Object.keys(patch).length === 0) return true;
  try {
    const db = await withTimeout(getDb());
    if (!db) return false;
    await withTimeout(db.doc("app/" + CONTENT_KEY).update({ value: patch }));
    return true;
  } catch {
    return false;
  }
}
async function deleteKey(key, shared) {
  if (!shared) {
    try { localStorage.removeItem(key); } catch { /* ignore */ }
    return;
  }
  try {
    const db = await withTimeout(getDb());
    if (!db) return;
    await withTimeout(db.doc("app/" + key).delete());
  } catch { /* ignore */ }
}

async function loadDayProgress(key) {
  const v = await getJSON(key, false);
  return v || { drill: false, focus: false, office: false };
}

